L000026	\title{
L000027	Symmetry-controlled thermal activation in pyramidal Coulomb clusters:\\ Testing Kramers-Langer theory
L000028	}
L000029	
L000030	\author{Akhil Ayyadevara}
L000031	
L000032	\affiliation{Raman Research Institute, C. V. Raman Avenue, Sadashivanagar, Bangalore 560080, India}
L000033	\author{Anand Prakash}
