L000418	
L000419	\section{Molecular dynamics simulations}
L000420	
L000421	To obtain the theoretical inversion rates, we perform extensive MD simulations by integrating the equations of motion for the 5-ion cluster. The ions are treated as point charges with mass $m$ interacting via the Coulomb force and the external trap potential. The interaction with the laser cooling field is modeled using the Langevin equation:
L000422	\begin{equation}
L000423	m \ddot{\mathbf{r}}_i = -\nabla_i V(\{\mathbf{r}\}) - \gamma \dot{\mathbf{r}}_i + \boldsymbol{\xi}_i(t),
L000424	\end{equation}
L000425	where $\gamma$ is the friction coefficient and $\boldsymbol{\xi}_i(t)$ is a stochastic force satisfying the fluctuation-dissipation theorem $\langle \xi_{i\alpha}(t) \xi_{j\beta}(t') \rangle = 2 m \gamma k_B T \delta_{ij} \delta_{\alpha\beta} \delta(t-t')$.
L000426	
L000427	\subsection{Numerical integration}
L000428	We use a modified Velocity Verlet integrator adapted for Langevin dynamics \cite{Jensen_2013}. The simulation proceeds in two phases. First, a damping phase ($t < t_{\text{damp}}$) where the system is initialized with random positions and a strong damping force is applied without thermal noise to rapidly settle the ions into the local minimum. Second, a thermal phase where the friction is set to the experimental cooling value ($\gamma / m \approx 6 \times 10^3 \, \text{s}^{-1}$) and the stochastic thermal force is activated. The trajectories are evolved for $10^9$ steps with a time step $\Delta t = 10^{-8}$ s.
L000429	
L000430	\begin{figure}[h]
L000431	\centering
L000432	\begin{minipage}{0.95\linewidth}
L000433	    \hrule height 1pt \vspace{3pt}
L000434	    \textbf{Algorithm 1:} Langevin Dynamics for Ion Inversion
L000435	    \vspace{3pt} \hrule \vspace{5pt}
L000436	
L000437	    \begin{algorithmic}[1]
L000438	        \State \textbf{Initialize:} Random positions $\mathbf{r}$ and velocities $\mathbf{v}$.
L000439	        \State \textbf{Parameters:} $\Delta t = 10^{-8}$\,s, $N_{\text{steps}} = 10^9$, \texttt{save\_interval = 100}, Temperature $T$.
L000440	        \State \textbf{Define Forces:} $\mathbf{F}_{\text{trap}}(\mathbf{r}) = - \nabla V_{\text{trap}}$, $\mathbf{F}_{\text{coul}}(\mathbf{r}) = - \nabla V_{\text{coul}}$.
L000441	        \State
L000442	        \For{$step = 1$ to $N_{\text{steps}}$}
L000443	            \If{$step < N_{\text{damp}}$} \Comment{Initial Damping}
L000444	                \State $\mathbf{F}_{\text{total}} = \mathbf{F}_{\text{trap}} + \mathbf{F}_{\text{coul}} - \gamma_{\text{high}} \mathbf{v}$
L000445	                \State Integrate equations of motion (Damped Verlet).
L000446	            \Else \Comment{Langevin Dynamics}
