L000448	                \State $\mathbf{F}_{\text{total}} = \mathbf{F}_{\text{trap}} + \mathbf{F}_{\text{coul}} - \gamma \mathbf{v} + \boldsymbol{\xi}$
L000449	                \State Update $\mathbf{r}(t+\Delta t)$ and $\mathbf{v}(t+\Delta t)$.
L000450	            \EndIf
L000451	            \State
L000452	            \If{$step \pmod{\text{save\_interval}} == 0$}
L000453	                \State Store $\psi_{30}$ of current configuration.
L000454	            \EndIf
L000455	        \EndFor
L000456	        \State \textbf{Post-Process:} Obtain dwell times $\tau$ from $\psi_{30}$ sign flips. Extract rate from the histogram of dwell times (Fig.~\ref{fig:dwell_times}).
